window.docContents[240].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--The--rfl--tactic":{"contents":"\n\nThe rfl tactic closes a goal of the shape a = a, for any a. It\nchecks that both sides of the equality are definitionally equal —\nthat is, that they reduce to the same term. (So, in particular, a\nterm is always definitionally equal to itself.)\n\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Rewriting","header":"2.2.4. The  rfl  tactic","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--The--rfl--tactic"}});